SELECT COUNT(*) AS total_orders
FROM `pplk8s-lab-001.silver.orders` AS orders
WHERE orders.order_date = DATE '2026-10-01';

SELECT COUNT(DISTINCT customer_id) AS total_customers
FROM `pplk8s-lab-001`.`silver`.`customers`
WHERE signup_date <= DATE '2026-09-30';

SELECT COUNT(*) AS total_messages_sent
FROM `pplk8s-lab-001.silver.outreach_messages` AS outreach_messages
WHERE outreach_messages.sent_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-03';

SELECT COUNT(orders.order_id) AS total_orders
FROM `pplk8s-lab-001.silver.orders` AS orders
WHERE orders.order_date = '2026-10-01';

SELECT COUNT(DISTINCT customer_id) AS monthly_active_customers
FROM `pplk8s-lab-001.silver.customer_actions`
WHERE event_date BETWEEN DATE_SUB(DATE '2026-10-03', INTERVAL 29 DAY) AND DATE '2026-10-03';

SELECT COUNT(*) AS message_count
FROM `pplk8s-lab-001.silver.outreach_messages` AS outreach_messages
WHERE outreach_messages.sent_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-03';

SELECT COUNT(*) AS shipped_orders_count
FROM `pplk8s-lab-001.silver.orders`
WHERE LOWER(status) = 'shipped';

SELECT COUNT(DISTINCT customer_id) AS total_customers
FROM `pplk8s-lab-001.silver.customers`
WHERE signup_date <= DATE '2026-09-30';

SELECT COUNT(DISTINCT customer_id) AS active_customers
FROM `pplk8s-lab-001.silver.customer_actions`
WHERE event_date BETWEEN DATE_SUB(DATE '2026-10-03', INTERVAL 6 DAY) AND DATE '2026-10-03';

SELECT COUNT(*) AS total_orders
FROM `pplk8s-lab-001.silver.orders` AS orders
WHERE orders.order_date = DATE '2026-10-01';
